html:
{% set certificate = frappe.db.get_value("LMS Certificate", doc.name, ["name", "member", "issue_date", "expiry_date", "course"], as_dict=True) %}
{% set member = frappe.db.get_value("User", doc.member, ["full_name"], as_dict=True) %}
{% set course = frappe.db.get_value("LMS Course", doc.course, ["title", "name", "image", "default_instructor"], as_dict=True) %}

{# Use frappe.utils.get_url for all image assets to ensure absolute paths that can support even pdf format #}
{% set logo = frappe.utils.get_url("/assets/one_lms/images/IKAS-certified.png") %}
{% set certified_logo = frappe.utils.get_url("/assets/one_lms/images/IKAS-stamp.png") %}
{% set background_image_url = frappe.utils.get_url("/assets/one_lms/images/IKAS-background.png") %}

{% set current_year = frappe.utils.now_datetime().year %}

{# --- IMPORTANT: Add these meta tags for PDF control --- #}
<meta name="pdfkit-orientation" content="Landscape"><style>@page { size: A4 landscape; margin: 0; }</style>
<meta name="pdfkit-page-size" content="A4">
<meta name="pdfkit-margin-top" content="0mm">
<meta name="pdfkit-margin-bottom" content="0mm">
<meta name="pdfkit-margin-left" content="0mm">
<meta name="pdfkit-margin-right" content="0mm">
{# --- END IMPORTANT META TAGS --- #}


<style type="text/css">
/* Universal box-sizing for predictable dimensions */
*, *::before, *::after {
  box-sizing: border-box;
}

/* Font Face - IMPORTANT: Use get_url for absolute paths for pdf support*/
@font-face {
  font-family: 'Certificate';
  src: url("{{frappe.utils.get_url('/assets/one_lms/css/forte.ttf')}}");
  font-weight: bold;
}

@font-face {
  font-family: 'heading';
  src: url("{{frappe.utils.get_url('/assets/one_lms/css/Castellar_Regular.ttf')}}");
  font-weight: normal;
}

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  width: 100%; 
}

body {
  -webkit-print-color-adjust: exact;
}

.certificate-format {
  width: 1000px;
  height: 650px;
  margin: 0 auto;
  position: relative;
  page-break-after: always;
  background: url('{{ background_image_url }}') no-repeat center center;
  background-size: 100% 100%;
  overflow: hidden;
}

.inner-border {
  width: 100%;
  height: 100%;
  position: relative;
  font-family: 'Calibri', sans-serif;
  color: #000;
}

.logo {
  position: absolute;
  top: 1px;
  left: -28px;
  width: 200px;
}

.cert-number {
  position: absolute;
  top: 50px;
  right: 50px;
  font-size: 12px;
  color: black;
  text-align: right;
}

.cert-label {
  color: grey;
}

.cert-value {
  color: black;
  font-weight: bold;
}

.title {
    left:0px;
  position: absolute;
  top: 220px;
  width: 100%;
  text-align: center;
  font-size: 34px;
  font-family: 'heading';
  letter-spacing: 1px;
}

.top-divider{
  position: absolute;
  top: 247px;
  left: 115px;
  width: 760px;
  border: none;
  border-top: 1.5px solid #000;
}

.subtitle {
  left:-20px;
  position: absolute;
  top: 273px;
  width: 100%;
  text-align: center;
  font-size: 1rem;
  font-family: 'heading';
  font-weight: normal;
  color: black;
  text-transform: uppercase;
}

.member-name {
  position: absolute;
  top: 327px;
  width: 100%;
  text-align: center;
  font-size: 42px;
  font-family: 'Certificate';
  font-weight: bold;
}

.top-certificate-divider {
  position: absolute;
  top: 359px;
  left: 115px;
  width: 760px;
  border: none;
  border-top: 1.5px solid #000;
}

.course-text {
  position: absolute;
  top: 378px;
  width: 100%;
  text-align: center;
  font-size: 21px;
  line-height: 1.6;
  padding: 0 80px;
}

.signature-left,
.signature-center,
.signature-right {
  position: absolute;
  bottom: 40px;
  width: 200px;
  text-align: center;
  font-size: 20px;
  font-family: 'Certificate';
}

.signature-left {
  left: 35px;
}

/*.signature-center for better WKHTMLtoPDF compatibility */
.signature-center {
  left: 478px;
  margin-left: -100px;
}

.signature-right {
  right: 50px;
}

.signature-name {
  font-weight: bold;
  margin-top: 5px;
  margin-left: 5px;
}

.signature-role {
  font-size: 16px;
  color:grey;
  font-family: 'Calibri', sans-serif;
}

.footer-divider {
  border: none;
  border-top: 1px solid #000;
  width: 140px;
  margin: 5px auto;
}
</style>

<div class="certificate-format"
     style="background: url('{{ background_image_url }}') no-repeat center center;
            background-size: 100% 100%;">
    <div class="inner-border">

    <!-- Logo -->
    <img class="logo" src="{{ logo }}">

    <!-- Certificate Number -->
    <div class="cert-number">
      <span class="cert-label">{{ _("Certificate No:") }}</span>
      <span class="cert-value">
        {{ current_year }}{{ _("-E-TRG-") }}{{ certificate.name }}
      </span>
    </div>

    <!-- Title -->
    <div class="title">
      <b>{{ _("CERTIFICATE OF COMPLETION") }}</b>
    </div>

      <hr class="top-divider">

    <!-- Subtitle -->
    <div class="subtitle">
      <b>{{ _("THIS IS TO CERTIFY THAT") }}</b>
    </div>

    <!-- Member Name -->
    <div class="member-name">
      {{ member.full_name }}
    </div>

    <!-- Divider below member name -->
    <hr class="top-certificate-divider">

    <!-- Course Text -->
    <div class="course-text">
      {{ _("Has successfully completed E-Learning training course on") }}
      <i><b>{{ course.title }}</b></i><br>
      {{ _("given by Kuwait Incheon Airport AVSEC Training Academy") }}
    </div>

    <!-- Signatures -->
    <div class="signature-left">
      <img src="{{ certified_logo }}" width="80"><br>
      <div class="signature-name">Hyung Shin Kim</div>
      <hr class="footer-divider">
      <div class="signature-role">Chairman & CEO</div>
    </div>

    <div class="signature-center">
      <div class="signature-name">{{ certificate.issue_date.strftime('%d-%m-%Y') }}</div>
      <hr class="footer-divider">
      <div class="signature-role">Date</div>
    </div>

    <div class="signature-right">
      <div class="signature-name" style=" margin-left: -31px;">{{ course.default_instructor or _("None") }}</div>
      <hr class="footer-divider">
      <div class="signature-role">Certified Instructor</div>
    </div>

  </div>
</div>
